#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

char parityBit(const string& data) {               // even parity
    int ones = count(data.begin(), data.end(), '1');
    return (ones % 2 == 0) ? '0' : '1';
}

bool checkEven(const string& frame) {
    return count(frame.begin(), frame.end(), '1') % 2 == 0;
}

int main() {
    string data = "1011001";
    string frame = data + parityBit(data);         // 10110010
    cout << "Sent:     " << frame << endl;

    string received = frame;
    received[2] = (received[2] == '1') ? '0' : '1'; // noise flips bit 2
    cout << "Received: " << received << " -> "
         << (checkEven(received) ? "OK" : "ERROR detected") << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

struct Packet {
    int seq;          // sequence number
    string data;
};

int main() {
    string message = "RESULTS OUT TODAY";
    int size = 5;
    vector<Packet> packets;
    for (int i = 0, s = 1; i < (int)message.size(); i += size, s++)
        packets.push_back({s, message.substr(i, size)});    // split into packets

    // packets arrive in a different order
    vector<Packet> arrived = {packets[2], packets[0], packets[3],
packets[1]};

    sort(arrived.begin(), arrived.end(),
         [](const Packet& a, const Packet& b) { return a.seq < b.seq; });

    string rebuilt;
    for (auto& p : arrived) rebuilt += p.data;
    cout << "Rebuilt: " << rebuilt << endl;
    return 0;
}

struct PacketHeader {
    string sourceIP;      // e.g. "192.168.1.10"
    string destIP;        // e.g. "142.250.183.4"
    int    sourcePort;    // e.g. 51544 (your browser)
    int    destPort;      // e.g. 443 (HTTPS)
    int    sequenceNo;    // position of this packet in the message
    int    totalPackets;
    char   parity;        // simple error check
};
